INSERT INTO english_questions (question, options, correct_option, explanation, difficulty) VALUES ('Choose the correct sentence:', '["He don''t know the answer.","He doesn''t knows the answer.","He doesn''t know the answer.","He don''t knows the answer."]'::jsonb, 2, '''Doesn''t'' is correct with ''he'' and the base form ''know''.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO english_questions (question, options, correct_option, explanation, difficulty) VALUES ('Choose the correct sentence:', '["Neither the teacher nor the students was present.","Neither the teacher nor the students were present.","Neither the teacher nor the students is present.","Neither the teacher nor the students has present."]'::jsonb, 1, 'With ''neither...nor'', the verb agrees with the nearer subject (students = were).', 'medium') ON CONFLICT (question) DO NOTHING;
