INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Newton''s first law is also called the law of:', '["Acceleration","Inertia","Reaction","Gravitation"]'::jsonb, 1, 'Newton''s First Law is the law of inertia.', 'easy') ON CONFLICT (question) DO NOTHING;
