INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The SI unit of energy is:', '["Watt","Newton","Joule","Pascal"]'::jsonb, 2, 'Energy is measured in Joules.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Pressure = ?', '["Force ├ù Area","Force / Area","Area / Force","Mass ├ù Area"]'::jsonb, 1, 'Pressure = Force ├╖ Area.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Boyle''s Law states that pressure is ___ proportional to volume at constant temperature:', '["Directly","Inversely","Not","Equally"]'::jsonb, 1, 'Boyle''s Law: P Γê¥ 1/V at constant temperature.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Charles'' Law states that volume is ___ proportional to temperature at constant pressure:', '["Inversely","Not","Directly","Equally"]'::jsonb, 2, 'Charles'' Law: V Γê¥ T at constant pressure.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The unit of power is:', '["Joule","Newton","Watt","Pascal"]'::jsonb, 2, 'Power is measured in Watts.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which waves do NOT require a medium?', '["Sound waves","Water waves","Electromagnetic waves","Seismic waves"]'::jsonb, 2, 'Electromagnetic waves (light, radio) travel through vacuum.', 'easy') ON CONFLICT (question) DO NOTHING;
