INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A convex lens is a ___ lens.', '["Diverging","Converging","Plane","Concave"]'::jsonb, 1, 'A convex lens converges light rays.', 'easy') ON CONFLICT (question) DO NOTHING;
