INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Electric power consumed by a 100╬⌐ resistor with 2A current:', '["200 W","400 W","50 W","100 W"]'::jsonb, 1, 'P = I┬▓R = 4 ├ù 100 = 400 W.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The critical temperature in superconductors is:', '["Temperature above which resistance is zero","Temperature at which resistance becomes zero","Room temperature","Boiling point"]'::jsonb, 1, 'Critical temperature is where resistance drops to zero in superconductors.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Half-life is:', '["Time for substance to decay completely","Time for half the substance to decay","Half of atomic mass","Average lifetime"]'::jsonb, 1, 'Half-life is the time for half of a radioactive sample to decay.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO physics_questions (question, options, correct_option, explanation, difficulty) VALUES ('╬▒-particles consist of:', '["2 protons + 2 neutrons","2 protons only","1 proton + 1 neutron","2 electrons"]'::jsonb, 0, 'Alpha particles are helium nuclei: 2 protons and 2 neutrons.', 'easy') ON CONFLICT (question) DO NOTHING;
