INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The atomic number of an element represents:', '["Number of neutrons","Number of protons","Mass number","Number of electrons only"]'::jsonb, 1, 'Atomic number = number of protons.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The atomic mass of Carbon is:', '["6","12","14","16"]'::jsonb, 1, 'Carbon has atomic mass 12 g/mol.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Isotopes are atoms of the same element with:', '["Same mass number","Different number of protons","Same atomic number but different mass number","Same number of neutrons"]'::jsonb, 2, 'Isotopes have same protons but different neutrons (different mass number).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Electron configuration of Sodium (Na, Z=11):', '["2,8,1","2,8,3","2,9","2,6,3"]'::jsonb, 0, 'Na has 11 electrons: 2 in first shell, 8 in second, 1 in third.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which subshell is filled after 3p?', '["3d","4s","4p","3f"]'::jsonb, 1, 'Aufbau principle: after 3p comes 4s.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The periodic table is arranged in order of increasing:', '["Mass number","Atomic mass","Atomic number","Neutron number"]'::jsonb, 2, 'Modern periodic table is arranged by increasing atomic number.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Elements in the same group have the same number of:', '["Neutrons","Electron shells","Valence electrons","Protons"]'::jsonb, 2, 'Elements in the same group have the same number of valence electrons.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The gas collected at cathode during electrolysis of water is:', '["Oxygen","Hydrogen","Carbon dioxide","Nitrogen"]'::jsonb, 1, 'At cathode: 2HΓü║ + 2eΓü╗ ΓåÆ HΓéé (hydrogen gas).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which type of bond is formed in HΓééO?', '["Ionic","Covalent","Metallic","Van der Waals only"]'::jsonb, 1, 'Water has covalent bonds (shared electron pairs) between H and O.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The molarity of a solution is defined as:', '["Moles of solute per litre of solution","Grams of solute per 100g","Moles per kg of solvent","Litres of solute per litre"]'::jsonb, 0, 'Molarity (M) = moles of solute ├╖ litres of solution.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('A catalyst _____ the activation energy of a reaction.', '["Increases","Does not change","Decreases","Eliminates"]'::jsonb, 2, 'Catalysts lower the activation energy, speeding up the reaction.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which of the following is a strong acid?', '["Acetic acid","Carbonic acid","Hydrochloric acid","Formic acid"]'::jsonb, 2, 'HCl is a strong acid ΓÇö it fully dissociates in water.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Reaction between an acid and a base is called:', '["Oxidation","Reduction","Neutralization","Hydrolysis"]'::jsonb, 2, 'Acid + Base ΓåÆ Salt + Water (neutralization reaction).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which of these has the highest electronegativity?', '["Sodium","Oxygen","Fluorine","Chlorine"]'::jsonb, 2, 'Fluorine has the highest electronegativity of all elements.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The rate of a reaction generally ___ with increase in temperature.', '["Decreases","Stays constant","Increases","Becomes zero"]'::jsonb, 2, 'Higher temperature gives particles more energy, increasing collision rate.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which law states: ''At constant temperature, the volume of a gas is inversely proportional to pressure''?', '["Charles'' Law","Avogadro''s Law","Boyle''s Law","Gay-Lussac''s Law"]'::jsonb, 2, 'Boyle''s Law: PΓéüVΓéü = PΓééVΓéé at constant temperature.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Organic chemistry is the study of compounds containing:', '["Nitrogen","Oxygen","Carbon","Sulfur"]'::jsonb, 2, 'Organic chemistry is the study of carbon-based compounds.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The simplest hydrocarbon is:', '["Ethane","Propane","Methane","Butane"]'::jsonb, 2, 'Methane (CHΓéä) is the simplest hydrocarbon.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Alkenes contain:', '["Only single bonds","A double bond between carbon atoms","Triple bond","Only aromatic bonds"]'::jsonb, 1, 'Alkenes have at least one carbon-carbon double bond (C=C).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Benzene has the molecular formula:', '["CΓéåHΓéüΓéé","CΓéåHΓéüΓéä","CΓéåHΓéå","CΓéåHΓéüΓéÇ"]'::jsonb, 2, 'Benzene is CΓéåHΓéå, an aromatic compound.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the oxidation state of Fe in FeΓééOΓéâ?', '["+2","+3","+4","+6"]'::jsonb, 1, 'In FeΓééOΓéâ: 2(Fe) + 3(ΓêÆ2) = 0 ΓåÆ Fe = +3.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Galvanization involves coating iron with:', '["Tin","Copper","Zinc","Chromium"]'::jsonb, 2, 'Galvanization is coating iron with zinc to prevent rusting.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which process separates mixtures by boiling points?', '["Filtration","Crystallization","Distillation","Chromatography"]'::jsonb, 2, 'Distillation separates mixtures based on different boiling points.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The process of converting starch into glucose using enzymes is:', '["Fermentation","Hydrolysis","Oxidation","Polymerization"]'::jsonb, 1, 'Hydrolysis with enzymes (amylase) breaks starch into glucose.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which gas turns limewater milky?', '["Oxygen","Carbon dioxide","Hydrogen","Nitrogen"]'::jsonb, 1, 'COΓéé + Ca(OH)Γéé ΓåÆ CaCOΓéâ (white precipitate) + HΓééO.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The pH of a solution with [HΓü║] = 10Γü╗Γü┤ mol/L is:', '["2","4","6","8"]'::jsonb, 1, 'pH = -log[HΓü║] = -log(10Γü╗Γü┤) = 4.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the common name of CaCOΓéâ?', '["Lime","Quicklime","Limestone","Slaked lime"]'::jsonb, 2, 'CaCOΓéâ is calcium carbonate, commonly known as limestone.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('CaO (quicklime) reacts with water to form:', '["CaCOΓéâ","Ca(OH)Γéé","CaClΓéé","CaΓéâ(POΓéä)Γéé"]'::jsonb, 1, 'CaO + HΓééO ΓåÆ Ca(OH)Γéé (slaked lime).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('The Haber process produces:', '["Sulfuric acid","Nitric acid","Ammonia","Sodium hydroxide"]'::jsonb, 2, 'Haber process: NΓéé + 3HΓéé Γçî 2NHΓéâ.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO chemistry_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which of the following is NOT an isotope of hydrogen?', '["Protium","Deuterium","Tritium","Helium"]'::jsonb, 3, 'Helium is a different element. Protium, deuterium, and tritium are hydrogen isotopes.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which of the following is an irrational number?', '["0.5","ΓêÜ2","4/5","0.75"]'::jsonb, 1, 'ΓêÜ2 cannot be expressed as a fraction, so it is irrational.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the additive inverse of ΓÇô7?', '["ΓÇô7","1/7","7","0"]'::jsonb, 2, 'The additive inverse of ΓÇô7 is 7 (they sum to zero).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the multiplicative inverse of 5?', '["ΓÇô5","5","1/5","0"]'::jsonb, 2, 'The multiplicative inverse of 5 is 1/5.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Evaluate: |ΓÇô15| + |ΓÇô5|', '["ΓÇô20","10","20","ΓÇô10"]'::jsonb, 2, '|ΓÇô15| = 15, |ΓÇô5| = 5. Sum = 20.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The HCF of 48, 60, and 84 is:', '["6","12","18","24"]'::jsonb, 1, 'HCF(48, 60, 84) = 12.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The LCM of 12, 18, and 24 is:', '["48","60","72","84"]'::jsonb, 2, 'LCM(12, 18, 24) = 72.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('If a = 12, b = 8, then (a┬▓ - b┬▓) / (a - b) = ?', '["16","18","20","22"]'::jsonb, 2, '(a┬▓-b┬▓)/(a-b) = (a+b) = 12+8 = 20.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which of the following is not a prime number?', '["97","91","89","83"]'::jsonb, 1, '91 = 7 ├ù 13, so it is not prime.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The number of prime numbers between 10 and 30 is:', '["4","5","6","7"]'::jsonb, 2, 'Primes: 11, 13, 17, 19, 23, 29 = 6 primes.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Solve: x┬▓ - 16 = 0', '["x = 4","x = ┬▒4","x = -4","x = 8"]'::jsonb, 1, 'x┬▓ = 16, x = ┬▒4.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The graph of y = x┬▓ is a:', '["Straight line","Parabola","Circle","Hyperbola"]'::jsonb, 1, 'y = x┬▓ is a parabola.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the value of sin 90┬░?', '["0","1/2","ΓêÜ3/2","1"]'::jsonb, 3, 'sin 90┬░ = 1.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('tan 30┬░ = ?', '["1","1/ΓêÜ3","ΓêÜ3","ΓêÜ3/2"]'::jsonb, 1, 'tan 30┬░ = 1/ΓêÜ3.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The product of roots of x┬▓ - 5x + 6 = 0 is:', '["5","6","-5","-6"]'::jsonb, 1, 'Product of roots = c/a = 6/1 = 6.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('If f(x) = x┬▓ + 1, then f(3) = ?', '["8","9","10","12"]'::jsonb, 2, 'f(3) = 3┬▓ + 1 = 9 + 1 = 10.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the derivative of x┬│?', '["x┬▓","3x┬▓","3x","x┬│"]'::jsonb, 1, 'd/dx(x┬│) = 3x┬▓.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Γê½2x dx = ?', '["x┬▓","x┬▓ + C","2x┬▓","2x┬▓ + C"]'::jsonb, 1, 'Γê½2x dx = x┬▓ + C.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('sin 30┬░ = ?', '["0","1/2","ΓêÜ3/2","1"]'::jsonb, 1, 'sin 30┬░ = 1/2.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('cos 60┬░ = ?', '["0","1/2","ΓêÜ3/2","1"]'::jsonb, 1, 'cos 60┬░ = 1/2.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the value of logΓéüΓéÇ(1000)?', '["2","3","4","10"]'::jsonb, 1, 'logΓéüΓéÇ(1000) = logΓéüΓéÇ(10┬│) = 3.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The determinant of matrix [[2,3],[4,5]] is:', '["ΓêÆ2","2","22","ΓêÆ22"]'::jsonb, 0, 'det = (2├ù5) - (3├ù4) = 10 - 12 = ΓêÆ2.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the limit of (x┬▓-1)/(x-1) as xΓåÆ1?', '["0","1","2","undefined"]'::jsonb, 2, 'Factor: (x+1)(x-1)/(x-1) = x+1. At x=1: 1+1 = 2.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('tan 45┬░ = ?', '["0","1","ΓêÜ3","undefined"]'::jsonb, 1, 'tan 45┬░ = 1.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The sum of first n natural numbers is:', '["n(n-1)/2","n(n+1)/2","n┬▓/2","n(n+2)/2"]'::jsonb, 1, 'Sum = n(n+1)/2.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is 5! (5 factorial)?', '["25","60","120","720"]'::jsonb, 2, '5! = 5├ù4├ù3├ù2├ù1 = 120.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('In how many ways can 5 people be arranged in a row?', '["25","60","120","720"]'::jsonb, 2, '5! = 120 arrangements.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the slope of the line 2x + 3y = 6?', '["2/3","ΓêÆ2/3","3/2","ΓêÆ3/2"]'::jsonb, 1, '3y = -2x + 6, y = -2/3 x + 2. Slope = -2/3.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The nth term of an AP with first term a and common difference d is:', '["a + nd","a + (n-1)d","a - nd","a - (n-1)d"]'::jsonb, 1, 'nth term = a + (n-1)d.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the equation of a circle with center (0,0) and radius 5?', '["x┬▓ + y┬▓ = 5","x┬▓ + y┬▓ = 25","x┬▓ + y┬▓ = 10","x┬▓ - y┬▓ = 25"]'::jsonb, 1, 'Circle equation: x┬▓ + y┬▓ = r┬▓ = 25.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('d/dx(sin x) = ?', '["ΓêÆcos x","cos x","ΓêÆsin x","tan x"]'::jsonb, 1, 'The derivative of sin x is cos x.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Γê½cos x dx = ?', '["ΓêÆsin x + C","sin x + C","cos x + C","tan x + C"]'::jsonb, 1, 'Γê½cos x dx = sin x + C.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The distance between points (1,2) and (4,6) is:', '["3","4","5","7"]'::jsonb, 2, 'd = ΓêÜ((4-1)┬▓ + (6-2)┬▓) = ΓêÜ(9+16) = ΓêÜ25 = 5.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('How many ways to choose 3 items from 5? (Γü╡CΓéâ)', '["10","15","20","60"]'::jsonb, 0, 'Γü╡CΓéâ = 5!/(3!├ù2!) = 10.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('sin┬▓╬╕ + cos┬▓╬╕ = ?', '["0","1","2","sin 2╬╕"]'::jsonb, 1, 'Pythagorean identity: sin┬▓╬╕ + cos┬▓╬╕ = 1.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The sum of interior angles of a hexagon is:', '["540┬░","720┬░","900┬░","360┬░"]'::jsonb, 1, 'Sum = (n-2) ├ù 180┬░ = (6-2) ├ù 180┬░ = 720┬░.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('If A = {1,2,3} and B = {3,4,5}, what is A Γê⌐ B?', '["{1,2,3,4,5}","{3}","{1,2}","{}"]'::jsonb, 1, 'Intersection contains common elements: {3}.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the quadratic formula for ax┬▓ + bx + c = 0?', '["x = (-b ┬▒ ΓêÜ(b┬▓-4ac))/2a","x = (-b ┬▒ ΓêÜ(b┬▓+4ac))/2a","x = (b ┬▒ ΓêÜ(b┬▓-4ac))/2a","x = (-b ┬▒ ΓêÜ(b┬▓-4ac))/a"]'::jsonb, 0, 'x = (-b ┬▒ ΓêÜ(b┬▓-4ac))/2a is the quadratic formula.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the derivative of e╦ú?', '["xe╦úΓü╗┬╣","e╦ú","e╦úΓü║┬╣","1/e╦ú"]'::jsonb, 1, 'The derivative of e╦ú is e╦ú.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The sum of an infinite GP with first term a and ratio r (|r|<1) is:', '["a/(1-r)","a/(1+r)","a(1-r)","ar/(1-r)"]'::jsonb, 0, 'Sum = a/(1-r) for |r| < 1.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the value of i┬▓ where i = ΓêÜ(-1)?', '["1","-1","i","-i"]'::jsonb, 1, 'i┬▓ = (ΓêÜ-1)┬▓ = -1.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('d/dx(ln x) = ?', '["x","1/x","ln x","e^x"]'::jsonb, 1, 'The derivative of ln x is 1/x.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The equation of a straight line with slope m and y-intercept c is:', '["y = mx + c","y = cx + m","x = my + c","y = m/x + c"]'::jsonb, 0, 'Slope-intercept form: y = mx + c.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the range of sin x?', '["[-1, 1]","[0, 1]","(-Γê₧, Γê₧)","[0, 2╧Ç]"]'::jsonb, 0, 'sin x ranges from -1 to 1.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The binomial expansion of (a+b)┬▓ is:', '["a┬▓ + b┬▓","a┬▓ + 2ab + b┬▓","a┬▓ - 2ab + b┬▓","2a┬▓ + 2b┬▓"]'::jsonb, 1, '(a+b)┬▓ = a┬▓ + 2ab + b┬▓.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('What is the probability of getting heads when tossing a fair coin?', '["0","1/4","1/2","1"]'::jsonb, 2, 'P(heads) = 1/2 for a fair coin.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Simplify: (3x┬▓)(4x┬│)', '["7xΓü╡","12xΓü╡","12xΓü╢","7xΓü╢"]'::jsonb, 1, '3├ù4 = 12, x┬▓├ùx┬│ = xΓü╡. Answer: 12xΓü╡.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Factor: x┬▓ - 9', '["(x+3)(x-3)","(x-3)┬▓","(x+3)┬▓","(x-9)(x+1)"]'::jsonb, 0, 'Difference of squares: x┬▓ - 9 = (x+3)(x-3).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Solve: 3x - 7 = 2x + 5', '["10","11","12","13"]'::jsonb, 2, '3x - 2x = 5 + 7 ΓåÆ x = 12.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Simplify: (2x - 3)┬▓', '["4x┬▓ - 9","4x┬▓ - 12x + 9","4x┬▓ + 9","4x┬▓ - 6x + 9"]'::jsonb, 1, '(2x-3)┬▓ = 4x┬▓ - 12x + 9.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO mathematics_questions (question, options, correct_option, explanation, difficulty) VALUES ('If f(x) = 2x┬▓ - 3x + 1, then f(2) = ?', '["1","3","4","5"]'::jsonb, 1, 'f(2) = 2(4) - 3(2) + 1 = 8 - 6 + 1 = 3.', 'easy') ON CONFLICT (question) DO NOTHING;
