INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a formal written order directing a bank to pay a specified sum to a named person.', '["Voucher","Draft","Cheque","Receipt"]'::jsonb, 2, 'A cheque is a written order to the bank to pay a specified amount.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a document issued by customs authorities allowing goods to be imported.', '["Permit","Invoice","Manifest","Licence"]'::jsonb, 0, 'An import permit is issued by customs to allow goods to be imported.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('Goods that are brought into a country from abroad are known as _____.', '["Exports","Imports","Entrepot","Transit goods"]'::jsonb, 1, 'Imports are goods brought into a country from abroad.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a large retail store selling a wide variety of goods under one roof.', '["Superstore","Departmental store","Franchise","Market"]'::jsonb, 1, 'A departmental store sells many types of goods under one roof.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The letter of _____ is a bank''s guarantee that a buyer''s payment will be received by the seller.', '["Credit","Guarantee","Intent","Exchange"]'::jsonb, 0, 'A Letter of Credit is a bank guarantee ensuring payment to the seller.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a middleman who sells goods on behalf of a principal and earns a commission.', '["Broker","Agent","Retailer","Wholesaler"]'::jsonb, 1, 'An agent sells goods on behalf of a principal and earns commission.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ order is a standing instruction to a bank to make regular payments on behalf of a customer.', '["Standing","Stop","Direct","Recurring"]'::jsonb, 0, 'A standing order is a regular bank instruction to make set payments.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ trade refers to trade within the boundaries of a country.', '["Foreign","Home","International","External"]'::jsonb, 1, 'Home (internal/domestic) trade takes place within a country.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a list of goods with their prices offered for sale.', '["Catalogue","Invoice","Receipt","Manifest"]'::jsonb, 0, 'A catalogue lists goods and their prices available for sale.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('Selling goods below cost price to drive out competition is called _____.', '["Discounting","Dumping","Undercutting","Subsidy"]'::jsonb, 1, 'Dumping is selling below cost price to eliminate competition.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a type of warehouse where goods can be stored without paying customs duty.', '["Free zone","Bonded warehouse","Cold storage","Transit shed"]'::jsonb, 1, 'A bonded warehouse allows storage without immediate payment of customs duty.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The practice of selling identical goods in different markets at different prices is called price _____.', '["Fixing","Discrimination","Control","Comparison"]'::jsonb, 1, 'Price discrimination is selling the same product at different prices in different markets.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ note is a document sent by the seller to inform the buyer that goods have been dispatched.', '["Advice","Delivery","Credit","Debit"]'::jsonb, 0, 'An advice note informs the buyer that goods have been dispatched.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is the total value of goods and services exported minus imports.', '["Trade deficit","Balance of trade","Current account","Budget surplus"]'::jsonb, 1, 'Balance of trade = value of exports minus value of imports.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a combination of firms under common ownership that reduces competition.', '["Cartel","Monopoly","Conglomerate","Trust"]'::jsonb, 1, 'A monopoly is a single firm dominating the market.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the use of electronic systems to carry out banking transactions.', '["E-banking","M-banking","Online shopping","Digital trade"]'::jsonb, 0, 'E-banking uses electronic systems for banking transactions.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('Goods sent out of a country to other countries are known as _____.', '["Imports","Exports","Transit goods","Entrepot"]'::jsonb, 1, 'Exports are goods sent out of a country.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a business owned and controlled by its members who share in the profits.', '["Partnership","Cooperative","Company","Franchise"]'::jsonb, 1, 'A cooperative is owned and run by its members for mutual benefit.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a fee charged by a government on imported goods.', '["Excise duty","Tariff","VAT","Subsidy"]'::jsonb, 1, 'A tariff is a government tax on imported goods.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a document used to make payments through a bank without using cash.', '["Cheque","Draft","Both a and b","Voucher"]'::jsonb, 2, 'Both cheques and drafts allow payments without using cash.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ insurance covers goods while they are being transported.', '["Fire","Marine","Life","Property"]'::jsonb, 1, 'Marine insurance covers goods during transportation.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a financial institution that accepts deposits and makes loans.', '["Insurance company","Stock exchange","Bank","Cooperative"]'::jsonb, 2, 'A bank accepts deposits from the public and provides loans.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a person who owes money to a business.', '["Creditor","Debtor","Shareholder","Partner"]'::jsonb, 1, 'A debtor owes money to the business.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a person to whom money is owed.', '["Debtor","Creditor","Director","Agent"]'::jsonb, 1, 'A creditor is owed money by the business.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a formal agreement between two parties.', '["Invoice","Contract","Receipt","Voucher"]'::jsonb, 1, 'A contract is a legally binding agreement between two parties.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ insurance compensates a business if key personnel are unable to work.', '["Life insurance","Key person insurance","Health insurance","Property insurance"]'::jsonb, 1, 'Key person insurance covers the financial loss from the incapacity of key staff.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ principle of insurance means the insured must have financial interest in the subject.', '["Indemnity","Insurable interest","Contribution","Subrogation"]'::jsonb, 1, 'Insurable interest means you must have a financial stake in what is insured.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a business organization owned by one person.', '["Partnership","Sole trader","Company","Cooperative"]'::jsonb, 1, 'A sole trader (sole proprietorship) is owned and run by one individual.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a fee paid by an importer to clear goods through customs.', '["Tariff","Customs duty","Excise duty","Port charge"]'::jsonb, 1, 'Customs duty is paid to clear imported goods through customs.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ combines the resources of two or more people to form a business.', '["Company","Cooperative","Partnership","Franchise"]'::jsonb, 2, 'A partnership combines resources of two or more partners.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is defined as the movement of goods from producers to consumers.', '["Production","Distribution","Marketing","Retailing"]'::jsonb, 1, 'Distribution is the movement of goods from producers to consumers.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a person who buys shares in a company.', '["Director","Shareholder","Creditor","Debtor"]'::jsonb, 1, 'A shareholder (stockholder) buys and owns shares in a company.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ market is where shares of publicly listed companies are traded.', '["Money","Stock","Bond","Commodity"]'::jsonb, 1, 'The stock market (stock exchange) trades company shares.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ duty is a tax on goods manufactured within a country.', '["Import","Customs","Excise","Value added"]'::jsonb, 2, 'Excise duty is levied on goods manufactured domestically.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ bank provides long-term loans to businesses and governments.', '["Central","Commercial","Development","Investment"]'::jsonb, 2, 'Development banks provide long-term finance for economic development.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is a form of promotion where a business pays for space in media to reach customers.', '["Advertising","Public relations","Sales promotion","Personal selling"]'::jsonb, 0, 'Advertising is paid promotion in media channels.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is the money paid to an employee based on sales they generate.', '["Salary","Wage","Commission","Bonus"]'::jsonb, 2, 'Commission is earnings based on sales performance.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ refers to transporting goods by sea.', '["Aviation","Rail freight","Shipping","Road transport"]'::jsonb, 2, 'Shipping (sea freight) refers to transporting goods by sea.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ of demand states that as price rises, quantity demanded falls.', '["Principle","Theory","Law","Rule"]'::jsonb, 2, 'The Law of Demand states price and quantity demanded are inversely related.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a business entity separate from its owners in law.', '["Partnership","Sole trader","Company","Cooperative"]'::jsonb, 2, 'A company has a separate legal identity from its owners.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is where foreign currencies are bought and sold.', '["Stock market","Money market","Foreign exchange market","Bond market"]'::jsonb, 2, 'The foreign exchange market (forex) trades currencies.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a written acknowledgment that a sum of money has been received.', '["Invoice","Receipt","Voucher","Note"]'::jsonb, 1, 'A receipt acknowledges payment has been received.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ trade refers to trade between two countries.', '["Multilateral","Bilateral","Internal","Transit"]'::jsonb, 1, 'Bilateral trade is trade between exactly two countries.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ combines several companies under one parent company.', '["Cartel","Conglomerate","Monopoly","Merger"]'::jsonb, 1, 'A conglomerate is a group of diverse companies under one parent.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ system allows businesses to sell products without stocking them.', '["Franchising","Dropshipping","Consignment","Agency"]'::jsonb, 1, 'Dropshipping allows selling products without holding inventory.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is the fee paid for the use of intellectual property.', '["Commission","Royalty","Rent","Dividend"]'::jsonb, 1, 'A royalty is paid for using someone else''s intellectual property.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the process of converting a private company into a public one.', '["Privatization","Flotation","Nationalization","Merger"]'::jsonb, 1, 'Flotation (going public/IPO) converts a private company to a public one.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a guarantee given by a manufacturer that a product will function properly.', '["Contract","Warranty","Bond","Certificate"]'::jsonb, 1, 'A warranty guarantees a product will work as described.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a document sent with a consignment of goods giving details of the goods.', '["Invoice","Delivery note","Manifest","Advice note"]'::jsonb, 1, 'A delivery note accompanies a consignment and lists its contents.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the practice of selling goods in another country below cost price.', '["Discounting","Dumping","Subsidizing","Undercutting"]'::jsonb, 1, 'Dumping is exporting goods below cost price to gain market share.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ capital is money invested in a business that is not expected to be repaid.', '["Loan","Equity","Debenture","Overdraft"]'::jsonb, 1, 'Equity capital is invested in exchange for ownership, not repaid.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ company is one whose shares are not available to the general public.', '["Public","Private","Government","Foreign"]'::jsonb, 1, 'A private limited company''s shares are not traded publicly.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ price is the price at which a security is first offered to the public.', '["Market","Issue","Face","Reserve"]'::jsonb, 1, 'The issue price is set at an IPO (Initial Public Offering).', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a business where one party licenses its brand to another party.', '["Agency","Franchise","Partnership","Joint venture"]'::jsonb, 1, 'A franchise licenses a brand/business model to franchisees.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ Act protects consumers from unfair trading practices.', '["Companies","Consumer Protection","Trade","Contract"]'::jsonb, 1, 'Consumer Protection Acts safeguard buyers from unfair practices.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('An official document permitting the export of specific goods is called an _____.', '["Export licence","Bill of lading","Certificate of origin","Customs permit"]'::jsonb, 0, 'An export licence grants official permission to export certain goods.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the movement of labor, capital, and goods between countries.', '["Trade","Globalization","Migration","Commerce"]'::jsonb, 1, 'Globalization refers to the flow of goods, capital, and labor across borders.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ allows a bank customer to withdraw more than what is in their account.', '["Loan","Overdraft","Credit card","Mortgage"]'::jsonb, 1, 'An overdraft facility lets customers spend beyond their account balance.', 'easy') ON CONFLICT (question) DO NOTHING;
