INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a company formed to carry out a specific project.', '["Subsidiary","Joint venture","Holding company","Franchise"]'::jsonb, 1, 'A joint venture is formed by two or more parties for a specific project.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ advertising aims to persuade customers to buy a particular product.', '["Informative","Persuasive","Reminder","Comparative"]'::jsonb, 1, 'Persuasive advertising aims to convince customers to purchase.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ Act regulates the formation and running of companies.', '["Trade","Companies Act","Consumer Protection","Competition"]'::jsonb, 1, 'The Companies Act governs company registration and management.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is defined as a business that sells goods in small quantities to the public.', '["Wholesaler","Retailer","Distributor","Agent"]'::jsonb, 1, 'A retailer sells goods directly to the end consumer in small quantities.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ occurs when a debtor cannot pay their debts.', '["Liquidation","Insolvency","Bankruptcy","Receivership"]'::jsonb, 1, 'Insolvency is the inability to pay debts when they fall due.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ ratio measures how quickly a company can pay its short-term liabilities.', '["Debt","Current ratio","Profit","Gearing"]'::jsonb, 1, 'The current ratio measures short-term liquidity (current assets ├╖ current liabilities).', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ note is issued when a seller grants a reduction in price to the buyer.', '["Debit","Credit","Advice","Delivery"]'::jsonb, 1, 'A credit note reduces the amount owed by the buyer.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is a method of selling where goods are offered to the highest bidder.', '["Tender","Auction","Consignment","Bulk selling"]'::jsonb, 1, 'An auction sells to the highest bidder.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a financial intermediary that helps companies raise capital.', '["Commercial bank","Merchant bank","Insurance company","Building society"]'::jsonb, 1, 'Merchant banks (investment banks) help companies raise capital.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a market where previously issued securities are bought and sold.', '["Primary market","Secondary market","Money market","Capital market"]'::jsonb, 1, 'The secondary market trades previously issued shares and bonds.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a sum of money paid to a broker for executing a transaction.', '["Commission","Brokerage","Fee","Royalty"]'::jsonb, 1, 'Brokerage is the fee paid to a broker for their services.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ trade barriers include quotas, tariffs, and embargoes.', '["Tariff","Non-tariff","Invisible","Formal"]'::jsonb, 1, 'Non-tariff barriers include quotas, subsidies, and embargoes.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a store that sells goods bought directly from producers at lower prices.', '["Retail store","Wholesale store","Factory outlet","Superstore"]'::jsonb, 1, 'A wholesale store sells in bulk at lower prices.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ value is the amount a business expects to sell an asset for at end of its useful life.', '["Book","Residual","Market","Historical"]'::jsonb, 1, 'Residual (scrap/salvage) value is the expected disposal value at end of asset life.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the process by which a business becomes larger through mergers and acquisitions.', '["Diversification","Integration","Expansion","Consolidation"]'::jsonb, 1, 'Integration (growth by mergers and acquisitions) makes businesses larger.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a document that gives permission to a ship to leave port.', '["Bill of lading","Clearance certificate","Manifest","Export licence"]'::jsonb, 1, 'A clearance certificate allows a ship to leave port.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The Pakistan Stock Exchange (PSX) is located in:', '["Islamabad","Lahore","Karachi","Peshawar"]'::jsonb, 2, 'Pakistan Stock Exchange (PSX) is headquartered in Karachi.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a retail outlet that sells goods to the public in large quantities at low prices.', '["Boutique","Superstore","Specialty store","Kiosk"]'::jsonb, 1, 'A superstore sells in large quantities at discounted prices.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which document proves ownership of goods during sea transit?', '["Invoice","Bill of lading","Insurance certificate","Delivery note"]'::jsonb, 1, 'The bill of lading serves as proof of ownership during sea shipment.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the total value of all goods and services produced in a country in a year.', '["GNP","GDP","NNP","NI"]'::jsonb, 1, 'GDP (Gross Domestic Product) is total output within a country''s borders.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a business where one party licenses its business model to another.', '["Cooperative","Franchise","Agency","Sole trader"]'::jsonb, 1, 'A franchise grants the right to use a business model in exchange for fees.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which type of account earns interest but has restrictions on withdrawals?', '["Current account","Savings account","Loan account","Credit account"]'::jsonb, 1, 'A savings account earns interest and may restrict frequent withdrawals.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a note issued by the buyer acknowledging goods have been returned to the seller.', '["Credit note","Debit note","Advice note","Delivery note"]'::jsonb, 1, 'A debit note is issued by the buyer when returning goods to the seller.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ of demand states that as price falls, quantity demanded rises.', '["Theory","Principle","Law","Model"]'::jsonb, 2, 'The Law of Demand establishes the inverse price-demand relationship.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a temporary fall in business activity.', '["Depression","Recession","Boom","Slump"]'::jsonb, 1, 'A recession is a temporary decline in economic/business activity.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which document is essential for clearing goods through customs?', '["Invoice only","Bill of entry","Delivery note","Advice note"]'::jsonb, 1, 'A bill of entry is the customs declaration required to clear goods.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a written promise to pay a certain sum at a future date.', '["Cheque","Promissory note","Bill of lading","Draft"]'::jsonb, 1, 'A promissory note is an unconditional promise to pay at a specified future date.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ trade barriers are in the form of direct taxes on imports.', '["Non-tariff","Tariff","Quota","Subsidy"]'::jsonb, 1, 'Tariff barriers are direct taxes (duties) imposed on imported goods.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is responsible for regulating and supervising banks in Pakistan.', '["Ministry of Finance","State Bank of Pakistan","SECP","NFC"]'::jsonb, 1, 'The State Bank of Pakistan (SBP) is the central bank and banking regulator.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a fee charged by a port for loading or unloading goods.', '["Wharfage/Port charge","Tariff","Customs duty","Freight charge"]'::jsonb, 0, 'Port/wharfage charges are fees for using port facilities.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which of the following is a direct tax in Pakistan?', '["Sales tax","Income tax","Customs duty","Excise duty"]'::jsonb, 1, 'Income tax is a direct tax levied on income earned.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO commerce_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a limit set by the government on the quantity of goods that can be imported.', '["Tariff","Quota","Embargo","Subsidy"]'::jsonb, 1, 'An import quota limits the quantity of a good that can be imported.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ equation states that Assets = Liabilities + Capital.', '["Business","Accounting","Financial","Economic"]'::jsonb, 1, 'The accounting equation: Assets = Liabilities + Capital.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a record of all transactions involving a specific account.', '["Journal","Ledger","Trial balance","Cash book"]'::jsonb, 1, 'A ledger is a book containing individual accounts.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is the first book of entry where transactions are first recorded.', '["Ledger","Trial balance","Journal","Cash book"]'::jsonb, 2, 'The journal (day book) is the book of prime entry.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the process of recording financial transactions in a systematic way.', '["Auditing","Bookkeeping","Accounting","Budgeting"]'::jsonb, 1, 'Bookkeeping is the systematic recording of financial transactions.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ sheet shows a company''s financial position at a specific date.', '["Income","Cash flow","Balance","Trading"]'::jsonb, 2, 'The balance sheet shows assets, liabilities, and capital at a point in time.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a list of all ledger balances used to check arithmetic accuracy.', '["Balance sheet","Trial balance","Journal","Ledger"]'::jsonb, 1, 'A trial balance lists all ledger account balances to verify debit = credit.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ account shows the gross profit or loss of a business.', '["Profit and Loss","Trading","Capital","Cash"]'::jsonb, 1, 'The Trading Account reveals gross profit (Sales ΓêÆ COGS).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the systematic allocation of the cost of an asset over its useful life.', '["Amortization","Depreciation","Depletion","Provision"]'::jsonb, 1, 'Depreciation allocates the cost of a fixed asset over its useful life.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is an amount owed by the business to outsiders.', '["Asset","Capital","Liability","Revenue"]'::jsonb, 2, 'A liability is money the business owes to external parties.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ method charges an equal amount of depreciation each year.', '["Reducing balance","Straight-line","Unit of production","Revaluation"]'::jsonb, 1, 'The straight-line method depreciates an asset by equal amounts annually.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ are costs that remain fixed regardless of the level of output.', '["Variable costs","Fixed costs","Semi-variable costs","Marginal costs"]'::jsonb, 1, 'Fixed costs do not change with the level of production.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is the difference between sales revenue and cost of goods sold.', '["Net profit","Gross profit","Operating profit","Contribution"]'::jsonb, 1, 'Gross Profit = Sales Revenue ΓêÆ Cost of Goods Sold.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ entry increases an asset or expense account.', '["Credit","Debit","Journal","Closing"]'::jsonb, 1, 'Debit entries increase asset and expense accounts.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ entry increases a liability or income account.', '["Debit","Contra","Credit","Adjusting"]'::jsonb, 2, 'Credit entries increase liability, capital, and income accounts.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is the final account that shows the net profit or loss.', '["Trading account","Balance sheet","Profit and Loss account","Cash flow"]'::jsonb, 2, 'The Profit and Loss Account shows net profit after all expenses.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ capital is the long-term finance invested by the owner in the business.', '["Working","Owner''s","Loan","Fixed"]'::jsonb, 1, 'Owner''s capital is the long-term investment made by the proprietor.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is an amount set aside from profits to meet future liabilities.', '["Reserve","Provision","Accrual","Prepayment"]'::jsonb, 1, 'A provision is set aside against a specific anticipated expense or loss.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ ratio measures the relationship between current assets and current liabilities.', '["Quick","Gearing","Current","Profitability"]'::jsonb, 2, 'Current Ratio = Current Assets ├╖ Current Liabilities.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ are expenses that have been incurred but not yet paid.', '["Prepaid expenses","Accrued expenses","Deferred income","Provisions"]'::jsonb, 1, 'Accrued expenses are incurred but not yet paid ΓÇö a current liability.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is income that has been received but not yet earned.', '["Accrued income","Prepayment (Deferred income)","Commission","Discount"]'::jsonb, 1, 'Prepaid/deferred income is cash received before the service is rendered.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ method of stock valuation assumes the most recently purchased items are sold first.', '["FIFO","AVCO","LIFO","Specific identification"]'::jsonb, 2, 'LIFO (Last In First Out) assumes newest stock is sold first.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ method of stock valuation assumes the earliest purchased items are sold first.', '["LIFO","AVCO","FIFO","Weighted average"]'::jsonb, 2, 'FIFO (First In First Out) assumes oldest stock is sold first.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the buying and selling of fixed assets for long-term use in the business.', '["Revenue expenditure","Capital expenditure","Working capital management","Stock control"]'::jsonb, 1, 'Capital expenditure is spending on long-term fixed assets.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is income received from selling goods and services.', '["Profit","Revenue","Capital","Interest"]'::jsonb, 1, 'Revenue is the income earned from normal business operations.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ reconciliation matches the bank statement with the cash book.', '["Journal","Bank","Trial balance","Ledger"]'::jsonb, 1, 'A bank reconciliation compares the cash book to the bank statement.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ shows all cash inflows and outflows of a business.', '["Balance sheet","Trial balance","Cash flow statement","Income statement"]'::jsonb, 2, 'The cash flow statement reports all cash receipts and payments.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ are assets that can be quickly converted into cash.', '["Fixed assets","Liquid assets","Intangible assets","Capital assets"]'::jsonb, 1, 'Liquid assets are quickly convertible to cash (e.g., cash, debtors).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is the minimum amount of cash a business needs to operate.', '["Working capital","Fixed capital","Liquid reserve","Cash buffer"]'::jsonb, 0, 'Working capital (current assets ΓêÆ current liabilities) funds day-to-day operations.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a person or business that is owed money by the business.', '["Debtor","Director","Creditor","Partner"]'::jsonb, 2, 'A creditor is owed money by the business.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ principle states that accounts should be prepared assuming the business will continue.', '["Accrual","Consistency","Going concern","Prudence"]'::jsonb, 2, 'The going concern concept assumes the business will continue operating.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the value of an asset after deducting accumulated depreciation.', '["Market value","Net book value","Residual value","Replacement value"]'::jsonb, 1, 'Net book value = Cost ΓêÆ Accumulated depreciation.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ convention requires expenses to be matched with the revenue they generate.', '["Prudence","Going concern","Matching","Consistency"]'::jsonb, 2, 'The matching concept matches expenses to the revenue they help generate.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the excess of liabilities over assets.', '["Surplus","Insolvency","Profit","Equity"]'::jsonb, 1, 'Insolvency is when liabilities exceed assets ΓÇö the business cannot pay its debts.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ note is issued when goods are returned to the supplier.', '["Credit","Advice","Debit","Invoice"]'::jsonb, 2, 'A debit note is issued by the buyer when returning goods to the supplier.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a record of all amounts owed by credit customers.', '["Purchases ledger","Sales ledger","Cash book","Petty cash"]'::jsonb, 1, 'The sales ledger records amounts owed by credit customers (debtors).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ are expenses that change in proportion to the level of output.', '["Fixed costs","Variable costs","Overheads","Sunk costs"]'::jsonb, 1, 'Variable costs rise and fall with the level of production.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is the point where total revenue equals total costs.', '["Margin of safety","Break-even point","Contribution","Profit point"]'::jsonb, 1, 'The break-even point is where total revenue = total costs (zero profit).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is an arrangement where a business receives goods now and pays later.', '["Loan","Trade credit","Mortgage","Overdraft"]'::jsonb, 1, 'Trade credit allows businesses to buy now and pay at a later date.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ accounting presents summary financial data to external stakeholders.', '["Management","Financial","Cost","Tax"]'::jsonb, 1, 'Financial accounting produces statements for external users like investors.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is the process of examining accounts to verify their accuracy and fairness.', '["Audit","Review","Investigation","Inspection"]'::jsonb, 0, 'An audit is an independent examination of financial records.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ are goods purchased for resale by a business.', '["Fixed assets","Inventory/Stock","Raw materials","Work-in-progress"]'::jsonb, 1, 'Inventory (stock) consists of goods held for resale.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is prepared to show how profit is divided among partners.', '["Trading account","Appropriation account","Capital account","Profit & Loss"]'::jsonb, 1, 'The appropriation account shows how profit is shared among partners.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ method charges depreciation as a fixed percentage of the declining balance.', '["Straight-line","Reducing balance","Revaluation","Units of production"]'::jsonb, 1, 'The reducing balance method applies a fixed rate to the decreasing book value.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ concept holds that items should be recorded at their original purchase price.', '["Going concern","Historical cost","Prudence","Consistency"]'::jsonb, 1, 'The historical cost concept records assets at original cost.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ profit is calculated after deducting all expenses from gross profit.', '["Gross","Net","Operating","Trading"]'::jsonb, 1, 'Net profit = Gross profit ΓêÆ All operating expenses.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is calculated by dividing net profit by capital employed.', '["Gross margin","Return on capital employed","Current ratio","Quick ratio"]'::jsonb, 1, 'ROCE = Net Profit ├╖ Capital Employed ├ù 100.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the amount by which revenue exceeds variable costs.', '["Net profit","Gross profit","Contribution","Margin of safety"]'::jsonb, 2, 'Contribution = Sales Revenue ΓêÆ Variable Costs.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ ratio compares liquid assets to current liabilities.', '["Current ratio","Quick (acid-test) ratio","Gearing ratio","Profit margin"]'::jsonb, 1, 'The quick ratio (acid-test) = (Current assets ΓêÆ stock) ├╖ Current liabilities.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ are assets held for long-term use in the business.', '["Current assets","Fixed (non-current) assets","Liquid assets","Working capital"]'::jsonb, 1, 'Fixed assets (non-current assets) are held for long-term use.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is an internal financial statement prepared for management use.', '["Balance sheet","Management account","Annual report","Prospectus"]'::jsonb, 1, 'Management accounts are prepared for internal decision-making.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the flow of cash in and out of a business over a period.', '["Working capital","Cash flow","Net profit","Revenue"]'::jsonb, 1, 'Cash flow tracks the movement of cash into and out of a business.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ measures the number of days it takes to collect amounts owed by debtors.', '["Creditor days","Debtor collection period","Stock turnover","Current ratio"]'::jsonb, 1, 'Debtor collection period = (Debtors ├╖ Credit sales) ├ù 365.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is the process of transferring journal entries to the ledger.', '["Balancing","Posting","Casting","Closing"]'::jsonb, 1, 'Posting is transferring journal entries to the appropriate ledger accounts.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a loan secured against property.', '["Overdraft","Debenture","Mortgage","Bond"]'::jsonb, 2, 'A mortgage is a long-term loan secured on property.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a document showing amounts owed by all debtors.', '["Trial balance","Debtors list","Sales ledger","Cash book"]'::jsonb, 1, 'A debtors list shows all outstanding amounts owed by credit customers.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is when income and expenses are recorded when earned or incurred, not when cash is received.', '["Cash accounting","Accrual accounting","Single entry","Management accounting"]'::jsonb, 1, 'Accrual accounting records transactions when they occur, regardless of cash movement.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a financial plan showing expected income and expenditure.', '["Forecast","Budget","Estimate","Projection"]'::jsonb, 1, 'A budget is a forward-looking financial plan.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the amount a company earns per share of its stock.', '["Dividend","Earnings per share (EPS)","Return on equity","Net margin"]'::jsonb, 1, 'EPS = Net profit ├╖ Number of shares issued.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is an official examination of a company''s financial records.', '["Internal review","Statutory audit","Management review","Tax inspection"]'::jsonb, 1, 'A statutory audit is a legally required independent examination of accounts.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ ratio measures how efficiently a company uses its assets.', '["Profit margin","Asset turnover","Current ratio","Return on capital"]'::jsonb, 1, 'Asset turnover = Sales ├╖ Total assets.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is a reduction in the value of an intangible asset over time.', '["Depreciation","Depletion","Amortization","Write-off"]'::jsonb, 2, 'Amortization is the gradual writing-off of intangible assets.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a list showing the balance of all accounts at the end of the period.', '["Balance sheet","Trial balance","Income statement","Journal"]'::jsonb, 1, 'A trial balance lists all ledger account balances.', 'easy') ON CONFLICT (question) DO NOTHING;
