INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ entry is made at the end of a period to update account balances.', '["Closing","Opening","Adjusting","Reversing"]'::jsonb, 2, 'Adjusting entries update accounts for accruals and prepayments at period end.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is the financial year used for tax and reporting purposes.', '["Calendar year","Accounting period","Fiscal year","Tax year"]'::jsonb, 1, 'The accounting period defines the time span covered by financial statements.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the difference between the face value and the price of a bond.', '["Premium","Discount","Interest","Dividend"]'::jsonb, 1, 'A bond discount is when the issue price is below face value.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a report on a company''s activities given to shareholders.', '["Management account","Annual report","Prospectus","Budget"]'::jsonb, 1, 'An annual report provides shareholders with financial and operational information.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is a financial statement that shows changes in equity.', '["Income statement","Cash flow statement","Statement of changes in equity","Balance sheet"]'::jsonb, 2, 'The statement of changes in equity details movements in shareholders'' funds.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ are items owned by a business that have monetary value.', '["Liabilities","Capital","Assets","Expenses"]'::jsonb, 2, 'Assets are resources owned by the business with economic value.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is an internal check to verify the accuracy of accounting records.', '["External audit","Statutory audit","Internal audit","Tax audit"]'::jsonb, 2, 'Internal audit reviews internal controls and accounting accuracy.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ standard requires businesses to use the same accounting methods consistently.', '["Prudence","Going concern","Consistency","Accrual"]'::jsonb, 2, 'The consistency concept ensures methods are applied the same way each period.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the cost of goods available for sale minus ending inventory.', '["Gross profit","Net profit","Cost of goods sold","Revenue"]'::jsonb, 2, 'COGS = Opening stock + Purchases ΓêÆ Closing stock.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is a card issued by a bank allowing immediate payment from a bank account.', '["Credit card","Debit card","Charge card","Smart card"]'::jsonb, 1, 'A debit card draws funds directly from the holder''s bank account.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ is the difference between selling price and variable cost per unit.', '["Net profit","Gross profit","Contribution margin","Mark-up"]'::jsonb, 2, 'Contribution margin = Selling price ΓêÆ Variable cost per unit.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the total amount of money owed to a business by its customers.', '["Creditors","Debtors","Cash","Revenue"]'::jsonb, 1, 'Debtors (accounts receivable) owe money to the business.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ account is used to record all transactions relating to the owner''s investment.', '["Cash","Capital account","Revenue","Reserve"]'::jsonb, 1, 'The capital account records the owner''s investment and withdrawals.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Goodwill is an example of:', '["Current asset","Tangible fixed asset","Intangible fixed asset","Current liability"]'::jsonb, 2, 'Goodwill is an intangible non-current asset.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which concept requires that potential losses be recorded immediately?', '["Accrual","Consistency","Prudence","Going concern"]'::jsonb, 2, 'The prudence concept requires caution ΓÇö anticipate losses but not gains.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Opening stock + Purchases ΓÇô Closing stock = ?', '["Gross profit","Net profit","Cost of goods sold","Net sales"]'::jsonb, 2, 'COGS = Opening stock + Purchases ΓêÆ Closing stock.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which of the following is a current liability?', '["Mortgage","Bank overdraft","Machinery","Goodwill"]'::jsonb, 1, 'A bank overdraft is a short-term current liability.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ records daily cash transactions.', '["Sales ledger","Cash book","Journal","Petty cash book"]'::jsonb, 1, 'The cash book records all receipts and payments of cash and bank.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Net profit is calculated as:', '["Gross profit ΓÇô Expenses","Revenue + Expenses","Sales ΓÇô Purchases only","Revenue ├ù Rate"]'::jsonb, 0, 'Net profit = Gross profit ΓêÆ All operating expenses.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ account records small day-to-day cash expenses.', '["Cash book","Petty cash account","Sundry account","Expenses account"]'::jsonb, 1, 'Petty cash covers minor routine expenses.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which financial ratio measures the percentage of profit relative to sales?', '["Current ratio","Asset turnover","Net profit margin","Gearing ratio"]'::jsonb, 2, 'Net profit margin = Net profit ├╖ Sales ├ù 100.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is an expense paid for in advance (e.g., insurance paid 6 months ahead).', '["Accrued expense","Prepaid expense","Deferred income","Provision"]'::jsonb, 1, 'A prepaid expense is paid before it is due ΓÇö a current asset.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ shows a business''s revenues and expenses over a period.', '["Balance sheet","Income statement (P&L)","Cash flow statement","Trial balance"]'::jsonb, 1, 'The income statement (profit and loss account) shows revenues and expenses.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Accumulated depreciation is shown on the:', '["Income statement","Trial balance only","Balance sheet as deduction from fixed assets","Cash flow statement"]'::jsonb, 2, 'Accumulated depreciation reduces the book value of fixed assets on the balance sheet.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is money withdrawn from the business by the owner for personal use.', '["Dividend","Drawings","Salary","Bonus"]'::jsonb, 1, 'Drawings are amounts withdrawn by the owner, reducing capital.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which of the following best describes capital expenditure?', '["Paying wages","Buying raw materials","Purchasing a delivery van","Paying rent"]'::jsonb, 2, 'Purchasing a fixed asset (delivery van) is capital expenditure.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ shows all sources and uses of funds in a period.', '["Cash flow statement","Funds flow statement","Balance sheet","Income statement"]'::jsonb, 1, 'The funds flow statement shows sources and applications of funds.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Stock that is unsold at the end of an accounting period is called:', '["Opening stock","Closing stock","Dead stock","Work-in-progress"]'::jsonb, 1, 'Closing stock is unsold inventory at the period end.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The purpose of a bank reconciliation is to:', '["Increase bank balance","Identify discrepancies between cash book and bank statement","Calculate profit","Audit expenses"]'::jsonb, 1, 'Bank reconciliation identifies and explains differences between internal records and the bank statement.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ is created when the business earns income before receiving cash.', '["Prepaid income","Accrued income","Deferred income","Sundry income"]'::jsonb, 1, 'Accrued income is earned but not yet received.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The double-entry principle states that every transaction has:', '["One entry only","Two equal and opposite entries","Three entries","No fixed number of entries"]'::jsonb, 1, 'Double-entry bookkeeping: every debit has an equal and opposite credit.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which account is debited when fixed assets are purchased for cash?', '["Cash account","Fixed asset account","Capital account","Revenue account"]'::jsonb, 1, 'When a fixed asset is bought, debit Fixed Asset account, credit Cash account.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('A _____ account shows the profit available to partners after all charges.', '["Trading","Appropriation","Capital","Cash"]'::jsonb, 1, 'The appropriation account divides net profit among partners.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('The _____ ratio shows how many times a business can cover its interest payments.', '["Current ratio","Interest cover ratio","Gearing ratio","Profit margin"]'::jsonb, 1, 'Interest cover = Operating profit ├╖ Interest charges.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO accounting_questions (question, options, correct_option, explanation, difficulty) VALUES ('_____ is the process of combining financial statements of a parent and its subsidiary.', '["Consolidation","Amalgamation","Merger","Acquisition"]'::jsonb, 0, 'Consolidation produces group financial statements combining parent and subsidiary accounts.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Economics is the study of:', '["Only money and banking","How society allocates scarce resources","Government policies only","International trade only"]'::jsonb, 1, 'Economics studies how individuals, businesses, and governments allocate scarce resources to satisfy unlimited wants.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Microeconomics studies:', '["National income","Individual firms and consumers","Inflation rates","Balance of payments"]'::jsonb, 1, 'Microeconomics focuses on individual economic units like consumers, firms, and specific markets.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('When price increases, demand generally:', '["Increases","Decreases","Stays the same","Doubles"]'::jsonb, 1, 'The law of demand states that as price rises, quantity demanded falls, all else equal.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A market is in equilibrium when:', '["Demand exceeds supply","Supply exceeds demand","Quantity demanded equals quantity supplied","Price is at its highest"]'::jsonb, 2, 'Equilibrium occurs when quantity demanded equals quantity supplied, clearing the market.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('GDP stands for:', '["Gross Domestic Product","General Domestic Product","Gross Development Plan","General Development Product"]'::jsonb, 0, 'GDP = Gross Domestic Product, the total value of goods and services produced in a country.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Inflation means:', '["Rising unemployment","Fall in price level","Rise in general price level","Economic growth"]'::jsonb, 2, 'Inflation is a sustained rise in the general price level of goods and services.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Price Elasticity of Demand (PED) measures:', '["Change in supply due to price change","Sensitivity of demand to price change","Rate of inflation","Consumer income change"]'::jsonb, 1, 'PED measures how much quantity demanded changes in response to a change in price.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A public good is characterized by:', '["High price and limited supply","Non-excludability and non-rivalry","Government ownership only","Being free to all"]'::jsonb, 1, 'Public goods are non-excludable (can''t be denied to anyone) and non-rival (one person''s use doesn''t reduce availability).', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Opportunity cost is:', '["The price paid for a good","The cost of the next best alternative foregone","Total cost of production","Fixed cost only"]'::jsonb, 1, 'Opportunity cost is the value of the next best alternative you give up when making a choice.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which of the following causes a shift in the demand curve?', '["Change in price of the good","Change in consumer income","Change in quantity supplied","Change in price alone"]'::jsonb, 1, 'Changes in income, tastes, prices of related goods shift the entire demand curve.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Perfect competition is characterized by:', '["Few sellers","Many buyers and sellers, identical products","One seller","Differentiated products"]'::jsonb, 1, 'Perfect competition has many buyers and sellers with homogeneous (identical) products.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A monopoly has:', '["Many sellers","Few sellers","One seller","Two sellers"]'::jsonb, 2, 'A monopoly exists when there is only one seller in a market with no close substitutes.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Consumer surplus is:', '["Extra goods bought","Difference between what consumer is willing to pay and what they actually pay","Profit made by consumers","Government subsidy"]'::jsonb, 1, 'Consumer surplus = the amount consumers are willing to pay minus the amount they actually pay.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Fiscal policy involves:', '["Central bank interest rates","Government spending and taxation","Exchange rate management","Trade policy"]'::jsonb, 1, 'Fiscal policy refers to government use of taxation and spending to influence the economy.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Unemployment caused by mismatch of skills is called:', '["Cyclical unemployment","Frictional unemployment","Structural unemployment","Seasonal unemployment"]'::jsonb, 2, 'Structural unemployment occurs due to a mismatch between workers'' skills and available jobs.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('According to the law of supply, as price increases, quantity supplied:', '["Decreases","Stays the same","Increases","Becomes zero"]'::jsonb, 2, 'The law of supply states that as price rises, quantity supplied increases, all else equal.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('GNP differs from GDP in that GNP includes:', '["Government spending","Net income from abroad","Investment","Consumer spending"]'::jsonb, 1, 'GNP = GDP + Net income earned abroad by citizens.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A negative externality occurs when:', '["Third parties bear costs of others'' economic activity","Third parties benefit from others'' activity","Government taxes production","Prices fall below equilibrium"]'::jsonb, 0, 'A negative externality imposes costs on third parties not involved in the transaction (e.g., pollution).', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Pakistan''s economy is classified as:', '["Developed economy","Developing/emerging economy","Fully planned economy","Subsistence economy"]'::jsonb, 1, 'Pakistan is classified as a developing/emerging economy.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which organization provides financial assistance to developing countries?', '["WTO","IMF","NATO","WHO"]'::jsonb, 1, 'The IMF (International Monetary Fund) provides financial assistance and loans to countries in economic difficulty.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The exchange rate is the rate at which:', '["Goods are traded","One currency is exchanged for another","Taxes are set","Wages are paid"]'::jsonb, 1, 'The exchange rate is the price of one currency in terms of another.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The balance of payments records a country''s economic transactions with:', '["Its own citizens","The rest of the world","The government","Private sector"]'::jsonb, 1, 'The balance of payments records all transactions between residents and the rest of the world.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Full employment means:', '["Zero unemployment","Only frictional unemployment remains","All workers have two jobs","No one is looking for work"]'::jsonb, 1, 'Full employment is when only frictional/natural unemployment remains.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The Phillips Curve shows the trade-off between:', '["Growth and inflation","Inflation and unemployment","Supply and demand","GDP and consumption"]'::jsonb, 1, 'The Phillips curve illustrates the inverse relationship between inflation and unemployment.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Marginal product is:', '["Total output divided by all workers","Additional output from one more unit of input","Average output per worker","Fixed output"]'::jsonb, 1, 'Marginal product = change in total output from employing one more unit of a factor.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('An externality exists when:', '["A firm earns profit","Third parties are affected by a transaction","Prices rise","Supply decreases"]'::jsonb, 1, 'Externalities occur when third parties bear costs or receive benefits from a transaction.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Public goods are:', '["Goods sold in public markets","Non-rival and non-excludable goods","Government-owned factories","Free goods with no cost"]'::jsonb, 1, 'Public goods are non-rival (use by one doesn''t reduce availability) and non-excludable.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A negative externality is:', '["A benefit to third parties","A cost imposed on third parties","A government tax","A subsidy"]'::jsonb, 1, 'Negative externalities impose costs on uninvolved third parties (e.g., pollution).', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Market failure occurs when:', '["Prices are too high","Resources are allocated inefficiently","Government intervenes","Firms make profits"]'::jsonb, 1, 'Market failure is when the market fails to allocate resources efficiently.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The indifference curve shows:', '["Production possibilities","Combinations of two goods giving equal satisfaction","Supply and demand","Cost and revenue"]'::jsonb, 1, 'An indifference curve shows all combinations of two goods yielding the same utility.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Income tax is deducted from:', '["Profits only","Wages at source","Company revenue","Imports"]'::jsonb, 1, 'Income tax (PAYE) is deducted from wages at the point of payment.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The fiscal multiplier measures:', '["Tax rates","Impact of a change in spending on national income","Money supply changes","Exchange rate effects"]'::jsonb, 1, 'The fiscal multiplier shows how much GDP changes for a given change in government spending.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('An oligopoly is a market structure with:', '["One seller","Two sellers","A few large sellers","Many small sellers"]'::jsonb, 2, 'An oligopoly is dominated by a small number of large firms.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A monopoly is a market dominated by:', '["Two firms","Many firms","A single seller","The government"]'::jsonb, 2, 'A monopoly has one seller with no close substitutes.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Perfect competition exists when:', '["One firm dominates","Few firms compete","There are many buyers and sellers with identical products","Firms set their own prices"]'::jsonb, 2, 'Perfect competition has many buyers and sellers, homogeneous products, and free entry/exit.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The interest rate is:', '["The cost of goods","Cost of borrowing money as a percentage","Rate of inflation","Tax rate"]'::jsonb, 1, 'The interest rate is the cost of borrowing money, expressed as a percentage.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Credit creation refers to:', '["Printing money","Process by which banks create money through lending","Government borrowing","Foreign exchange"]'::jsonb, 1, 'Banks create money through the process of lending (credit creation/money multiplier).', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Aggregate supply is the:', '["Total demand in an economy","Total supply of goods and services in an economy","Government supply of money","Export supply"]'::jsonb, 1, 'Aggregate supply is the total output all producers are willing to supply at different price levels.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Aggregate demand includes:', '["Consumer spending only","Consumer + investment + government + net exports","Supply side only","Imports only"]'::jsonb, 1, 'AD = C + I + G + (XΓêÆM): consumption, investment, government spending, net exports.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The business cycle refers to:', '["A company''s annual report","Periods of expansion and contraction in economic activity","Product life cycle","Business planning"]'::jsonb, 1, 'The business cycle describes the fluctuations in economic activity over time.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Privatization is:', '["Government taking over private companies","Transfer of publicly owned businesses to private ownership","Increasing taxes","Reducing imports"]'::jsonb, 1, 'Privatization transfers state-owned enterprises to private ownership.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The money supply refers to:', '["Government budget","Total amount of money in circulation in an economy","Foreign reserves","Interest rate"]'::jsonb, 1, 'The money supply is the total stock of money available in an economy.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The quantity theory of money states that:', '["More money causes less inflation","Price level is determined by the quantity of money","Interest rates determine prices","Wages determine inflation"]'::jsonb, 1, 'The quantity theory (MV = PQ) links money supply to the price level.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Sustainable development means:', '["Industrial growth at any cost","Economic growth without harming future generations","No development","Government-led growth"]'::jsonb, 1, 'Sustainable development meets present needs without compromising future generations.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Marginal propensity to consume (MPC) is:', '["Total spending on consumption","Proportion of additional income that is consumed","Average consumption","Fixed spending"]'::jsonb, 1, 'MPC = change in consumption ├╖ change in income.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A budget deficit occurs when:', '["Government revenue exceeds spending","Government spending exceeds revenue","Exports exceed imports","GDP grows fast"]'::jsonb, 1, 'A budget deficit is when government expenditure exceeds tax revenue.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A budget surplus exists when:', '["Spending exceeds revenue","Revenue exceeds spending","Trade is balanced","Money supply increases"]'::jsonb, 1, 'A budget surplus means government revenue exceeds its expenditure.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Contractionary monetary policy:', '["Increases money supply","Reduces money supply to control inflation","Lowers interest rates","Increases government spending"]'::jsonb, 1, 'Contractionary monetary policy reduces money supply/raises interest rates to curb inflation.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Marginal utility is:', '["Total satisfaction from consumption","Additional satisfaction from one more unit","Average utility","Minimum utility"]'::jsonb, 1, 'Marginal utility is the extra satisfaction from consuming one more unit.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The law of diminishing marginal utility states that:', '["Utility always increases","Additional satisfaction decreases as consumption increases","Prices rise with consumption","Income falls"]'::jsonb, 1, 'As you consume more of a good, each additional unit gives less extra satisfaction.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A progressive tax is one where:', '["Rate is same for everyone","Rate increases as income increases","Rate decreases with income","Only businesses pay"]'::jsonb, 1, 'Progressive tax: higher earners pay a higher percentage of their income.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A regressive tax is one where:', '["Rate rises with income","Rate decreases as income increases","Everyone pays equally","Only imports are taxed"]'::jsonb, 1, 'Regressive tax takes a larger proportion from lower-income earners.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The income effect refers to:', '["Change in demand due to taste","When a price fall increases real purchasing power","Change in supply","Effect of interest rates"]'::jsonb, 1, 'The income effect: when a price falls, real income rises, affecting demand.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The substitution effect states that:', '["More income leads to more spending","When a good becomes cheaper, consumers buy more of it instead of substitutes","Wages replace capital","Exports substitute imports"]'::jsonb, 1, 'Substitution effect: when a good''s price falls, consumers substitute it for relatively dearer alternatives.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A complementary good has:', '["Positive cross-price elasticity","Negative cross-price elasticity","Zero price elasticity","Infinite elasticity"]'::jsonb, 1, 'Complementary goods (e.g., cars and petrol) have negative cross-price elasticity.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A substitute good has:', '["Negative cross-price elasticity","Positive cross-price elasticity","Zero income elasticity","Inelastic demand"]'::jsonb, 1, 'Substitute goods have positive cross-price elasticity ΓÇö if one''s price rises, demand for the other rises.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The Production Possibility Frontier (PPF) shows:', '["Cost of production","All combinations of two goods that can be produced with given resources","Demand schedule","Market equilibrium"]'::jsonb, 1, 'The PPF shows the maximum possible output combinations with given resources and technology.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Comparative advantage means:', '["Having the best technology","Producing goods at the lowest opportunity cost","Highest absolute output","Most workers"]'::jsonb, 1, 'Comparative advantage is producing a good at a lower opportunity cost than another country.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The Gini coefficient measures:', '["GDP growth rate","Inequality in income distribution","Inflation rate","Unemployment rate"]'::jsonb, 1, 'The Gini coefficient ranges from 0 (perfect equality) to 1 (perfect inequality).', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Cyclical unemployment is caused by:', '["Workers changing jobs","Skill mismatches","Lack of aggregate demand (recession)","Seasonal factors"]'::jsonb, 2, 'Cyclical (demand-deficient) unemployment rises during recessions.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Frictional unemployment occurs when:', '["Workers lack skills","Workers are temporarily between jobs","Economy is in recession","Structural changes occur"]'::jsonb, 1, 'Frictional unemployment is temporary unemployment while searching for a new job.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Structural unemployment is caused by:', '["Economic downturns","Changing jobs voluntarily","Skills mismatch due to structural change","Seasonal demand"]'::jsonb, 2, 'Structural unemployment results from skills becoming obsolete due to industry changes.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Crowding out refers to:', '["Businesses entering new markets","Government borrowing reducing funds for private sector","Firms being pushed out of markets","Population growth"]'::jsonb, 1, 'Crowding out: high government borrowing raises interest rates, reducing private investment.', 'hard') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A government bond is:', '["A foreign currency","A financial asset issued by government to raise funds","A type of tax","A central bank reserve"]'::jsonb, 1, 'Government bonds are debt instruments issued to borrow money from investors.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The current account records:', '["Capital flows","Difference between exports and imports of goods and services","Government spending","Bank deposits"]'::jsonb, 1, 'The current account shows trade in goods/services, income flows, and transfers.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The circular flow of income shows:', '["Money flowing in rivers","Flow of money between households and firms","Government tax collection","Banking system"]'::jsonb, 1, 'The circular flow shows income flowing between households (as consumers/workers) and firms.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The base rate is:', '["Lowest tax rate","Rate at which central bank lends to commercial banks","Government spending rate","Minimum wage"]'::jsonb, 1, 'The base rate (bank rate) is the interest rate at which the central bank lends to commercial banks.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Currency depreciation means:', '["Rise in external value of currency","Fall in external value of currency","Rise in domestic prices","Fall in interest rates"]'::jsonb, 1, 'Depreciation is a fall in a currency''s value relative to other currencies.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Revaluation is:', '["Reducing the value of currency","Increasing external value of currency under a fixed exchange rate","Printing more money","Increasing tariffs"]'::jsonb, 1, 'Revaluation is an official increase in a currency''s value under a fixed exchange rate system.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The output gap is:', '["Gap between rich and poor","Difference between actual and potential GDP","Trade balance gap","Unemployment gap"]'::jsonb, 1, 'The output gap measures whether the economy is operating above or below its productive potential.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Capital goods are:', '["Consumer goods","Goods used in the production of other goods","Luxury goods","Financial assets"]'::jsonb, 1, 'Capital goods (machinery, equipment) are used to produce other goods.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('National debt is:', '["Individual citizens'' debts","Total money government owes to lenders","Trade deficit","Foreign investment"]'::jsonb, 1, 'National debt is the accumulated borrowing of the government.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Capitalism is an economic system where:', '["Government owns all resources","Private individuals own means of production","Resources are equally shared","The state plans all production"]'::jsonb, 1, 'Capitalism is characterized by private ownership of the means of production.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The primary sector includes:', '["Manufacturing","Banking and finance","Extraction of natural resources","Education"]'::jsonb, 2, 'The primary sector involves extracting natural resources (mining, agriculture, fishing).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The secondary sector involves:', '["Services","Natural resource extraction","Manufacturing and processing","Banking"]'::jsonb, 2, 'The secondary sector transforms raw materials into finished goods.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The tertiary sector includes:', '["Farming","Mining","Manufacturing","Services such as banking and education"]'::jsonb, 3, 'The tertiary sector provides services to businesses and consumers.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Labour productivity is:', '["Total number of workers","Increase in output per worker over time","Average wages","Unemployment rate"]'::jsonb, 1, 'Labour productivity measures output per worker.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The trade balance is:', '["Government''s fiscal balance","Difference between the value of exports and imports","Money supply minus debt","Consumer spending minus savings"]'::jsonb, 1, 'Trade balance = exports ΓêÆ imports of goods.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Economies of scale occur when:', '["Average costs rise with output","A firm can produce at lower cost as it grows larger","Small firms become less efficient","Wages increase"]'::jsonb, 1, 'Economies of scale reduce average costs as output increases.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Diseconomies of scale occur when:', '["Average costs fall with output","Average costs rise as output increases beyond a certain point","Small firms benefit","Wages fall"]'::jsonb, 1, 'Diseconomies of scale cause average costs to rise beyond the optimal scale.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Labour mobility refers to:', '["Workers cycling to work","Movement of workers between jobs and regions","Wage flexibility","Number of hours worked"]'::jsonb, 1, 'Labour mobility describes how easily workers can move between jobs and locations.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Information failure is a market failure where:', '["Markets have too many sellers","Consumers or producers lack information for optimal decisions","Prices are too high","Government intervenes too much"]'::jsonb, 1, 'Information failure leads to suboptimal market outcomes due to incomplete information.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A maximum price (price ceiling) is set:', '["Above equilibrium to protect producers","Below equilibrium to help consumers","Equal to equilibrium","By firms, not government"]'::jsonb, 1, 'A price ceiling is set below equilibrium, keeping prices low for consumers.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A minimum price (price floor) is set:', '["Below equilibrium to help consumers","Above equilibrium to protect producers","At equilibrium","To reduce production"]'::jsonb, 1, 'A price floor is set above equilibrium to guarantee producers a minimum price.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Free trade refers to:', '["Trade with no money involved","Trade agreement eliminating tariffs between countries","Government-controlled trade","Trade within one country"]'::jsonb, 1, 'Free trade involves removing barriers (tariffs, quotas) to international trade.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Economic growth is measured by:', '["Rising prices","Increase in real GDP over time","Fall in unemployment only","Rising exports"]'::jsonb, 1, 'Economic growth is the increase in real GDP (inflation-adjusted output).', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Allocative inefficiency means:', '["Too much output","Resources not used to produce goods most valued by consumers","Too little government spending","Excess supply"]'::jsonb, 1, 'Allocative inefficiency occurs when resources are not directed to their highest-valued use.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The real interest rate is:', '["The bank''s stated rate","Nominal interest rate adjusted for inflation","Rate set by firms","Minimum wage rate"]'::jsonb, 1, 'Real interest rate = Nominal interest rate ΓêÆ Inflation rate.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Nationalisation is when:', '["A firm expands abroad","Government takes over ownership of a private company","Private sector grows","Currency loses value"]'::jsonb, 1, 'Nationalisation transfers private businesses into government ownership.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A free trade area is:', '["A place with no shops","A group of countries that trade freely among themselves","A government market","An online marketplace"]'::jsonb, 1, 'A free trade area is a group of countries that remove trade barriers among themselves.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The floating exchange rate system is where:', '["Exchange rates are fixed","Exchange rates are determined by market forces","Government sets rates daily","Rates are pegged to gold"]'::jsonb, 0, 'Under a floating exchange rate, market supply and demand determine currency values.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('GNP differs from GDP because GNP includes:', '["Government spending","Net income earned abroad by citizens","Imports","Consumer spending"]'::jsonb, 1, 'GNP = GDP + net income from abroad (earnings of citizens abroad minus foreigners'' earnings locally).', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Marginal propensity to save (MPS) is:', '["Total savings","Proportion of additional income that is saved","Average savings rate","Fixed savings"]'::jsonb, 1, 'MPS = change in savings ├╖ change in income. MPC + MPS = 1.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('GDP per capita is:', '["Total GDP","GDP divided by population","GDP minus imports","GDP plus remittances"]'::jsonb, 1, 'GDP per capita = GDP ├╖ population. It measures average living standards.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('A recession is defined as:', '["One quarter of negative growth","Two consecutive quarters of negative GDP growth","Rising inflation","Falling wages"]'::jsonb, 1, 'A recession is technically two consecutive quarters of negative GDP growth.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Consumer surplus is the difference between:', '["Cost and profit","What consumers are willing to pay and what they actually pay","Wages and savings","Supply and demand"]'::jsonb, 1, 'Consumer surplus = willingness to pay ΓêÆ actual price paid.', 'medium') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('The State Bank of Pakistan primarily controls:', '["Fiscal policy","Monetary policy","Trade policy","Education policy"]'::jsonb, 1, 'The State Bank of Pakistan (SBP) is responsible for monetary policy.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Pakistan''s main export commodity historically has been:', '["Oil","Cotton and textiles","Machinery","Electronics"]'::jsonb, 1, 'Cotton and textile products have historically been Pakistan''s largest export.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Which tax is imposed on the value added at each stage of production in Pakistan?', '["Income tax","Customs duty","Sales Tax (GST)","Excise duty"]'::jsonb, 2, 'General Sales Tax (GST) in Pakistan is levied on value added at each stage.', 'easy') ON CONFLICT (question) DO NOTHING;
INSERT INTO economics_questions (question, options, correct_option, explanation, difficulty) VALUES ('Remittances in Pakistan''s economy refer to:', '["Government transfers","Money sent home by overseas Pakistanis","Bank loans","Export earnings"]'::jsonb, 1, 'Remittances are funds sent by overseas Pakistanis to their families, a major source of foreign exchange.', 'easy') ON CONFLICT (question) DO NOTHING;
